// --- TestCodecBuilderCloneIsolation ---
func TestCodecBuilderCloneIsolation(t *testing.T) {
	base := json.NewCodec(json.SnakeCase{})
	c1 := base.Omit("Password")
	c2 := base.Rename("FirstName", "given_name")
	u := CodecUser{FirstName: "Ada", LastName: "Lovelace", Age: 36, Password: "secret"}
	b1, err_31 := c1.Encode(u)
	if err_31 != nil {
		panic(fmt.Sprintf("%v", err_31))
	}
	b2, err_32 := c2.Encode(u)
	if err_32 != nil {
		panic(fmt.Sprintf("%v", err_32))
	}
	s1 := string(b1)
	s2 := string(b2)
	test.AssertFalse(t, strings.Contains(s1, "password"))
	test.AssertTrue(t, strings.Contains(s1, "first_name"))
	test.AssertTrue(t, strings.Contains(s2, "given_name"))
	test.AssertTrue(t, strings.Contains(s2, "password"))
}

// sampleGet is a realistic payload exercising nested objects, arrays,
// and mixed scalar types.
const sampleGet = `{"person":{"name":{"first":"Leonid","last":"Bugaev","fullName":"Leonid Bugaev"},"github":{"handle":"buger","followers":109,"verified":true},"avatars":[{"url":"https://example.com/a1.png","type":"thumbnail"},{"url":"https://example.com/a2.png","type":"full"}]},"company":{"name":"Acme","size":250},"tags":["go","json",null,true,3.14],"active":true,"score":42.5}`

// --- TestGet ---
type GetCase struct {
	name string
	keys []string
	kind string
}

func TestLookup(t *testing.T) {
	doc := `{"person": {"name": "Ada", "avatars": ["a.png", "b.png"]}}`
	t.Run("found nested value", func(t *testing.T) {
		r := json.Lookup(doc, json.KeyOf("person"), json.KeyOf("name"))
		if f, _isOk := r.(json.Found); _isOk {
			if s, _isOk := f.Value.(json.Str); _isOk {
				test.AssertEqual(t, s.Value, "Ada")
				return
			}
			t.Fatal("expected Str value")
			return
		}
		t.Fatal("expected Found")
	})
	t.Run("index segment addresses arrays", func(t *testing.T) {
		r := json.Lookup(doc, json.KeyOf("person"), json.KeyOf("avatars"), json.IndexOf(1))
		if f, _isOk := r.(json.Found); _isOk {
			if s, _isOk := f.Value.(json.Str); _isOk {
				test.AssertEqual(t, s.Value, "b.png")
				return
			}
			t.Fatal("expected Str value")
			return
		}
		t.Fatal("expected Found")
	})
	t.Run("absent path yields Missing not Invalid", func(t *testing.T) {
		r := json.Lookup(doc, json.KeyOf("person"), json.KeyOf("missing"))
		if _, _isOk := r.(json.Missing); _isOk {
			return
		}
		t.Fatal("expected Missing")
	})
	t.Run("structural mismatch yields Invalid", func(t *testing.T) {
		r := json.Lookup(doc, json.KeyOf("person"), json.KeyOf("name"), json.IndexOf(0))
		if bad, _isOk := r.(json.Invalid); _isOk {
			test.AssertError(t, bad.Error)
			return
		}
		t.Fatal("expected Invalid")
	})
	t.Run("malformed document yields Invalid", func(t *testing.T) {
		r := json.Lookup("{not json", json.KeyOf("person"))
		if bad, _isOk := r.(json.Invalid); _isOk {
			test.AssertError(t, bad.Error)
			return
		}
		t.Fatal("expected Invalid")
	})
}

// --- TestStringAt ---
func TestStringAt(t *testing.T) {
	doc := `{"person": {"name": "Grace"}}`
	t.Run("reads a string via segments", func(t *testing.T) {
		s, err_33 := json.StringAt(doc, json.KeyOf("person"), json.KeyOf("name"))
		if err_33 != nil {
			panic(fmt.Sprintf("%v", err_33))
		}
		test.AssertEqual(t, s, "Grace")
	})
	t.Run("missing path surfaces ErrPathNotFound", func(t *testing.T) {
		_, err := json.StringAt(doc, json.KeyOf("nope"))
		test.AssertError(t, err)
	})
}

// Lookup must validate the whole document before returning Found — a
// valid prefix at the requested path with trailing garbage after the
// top-level value is not a valid document and must surface as Invalid.
func TestLookupRejectsTrailingGarbage(t *testing.T) {
	doc := `{"person": {"name": "Ada"}} GARBAGE`
	r := json.Lookup(doc, json.KeyOf("person"), json.KeyOf("name"))
	if _, _isOk := r.(json.Found); _isOk {
		t.Errorf("Lookup returned Found for a document with trailing garbage: %v", r)
		return
	}
	if _, _isOk := r.(json.Missing); _isOk {
		t.Errorf("Lookup returned Missing for a document with trailing garbage")
		return
	}
	if bad, _isOk := r.(json.Invalid); _isOk {
		test.AssertError(t, bad.Error)
		return
	}
	t.Errorf("unexpected LookupResult variant: %v", r)
}

// LookupBytes (the bytes variant) must validate the whole document too.
func TestLookupBytesRejectsTrailingGarbage(t *testing.T) {
	doc := []byte(`{"person": {"name": "Ada"}} GARBAGE`)
	r := json.LookupBytes(doc, json.KeyOf("person"), json.KeyOf("name"))
	if _, _isOk := r.(json.Found); _isOk {
		t.Errorf("LookupBytes returned Found for a document with trailing garbage: %v", r)
		return
	}
	if _, _isOk := r.(json.Missing); _isOk {
		t.Errorf("LookupBytes returned Missing for a document with trailing garbage")
		return
	}
	if bad, _isOk := r.(json.Invalid); _isOk {
		test.AssertError(t, bad.Error)
		return
	}
	t.Errorf("unexpected LookupResult variant: %v", r)
}

// A valid document with no trailing garbage still returns Found (guard
// against over-validation that rejects well-formed input).
func TestLookupAcceptsWellFormedDocument(t *testing.T) {
	doc := `{"person": {"name": "Ada"}}`
	r := json.Lookup(doc, json.KeyOf("person"), json.KeyOf("name"))
	if f, _isOk := r.(json.Found); _isOk {
		if s, _isOk := f.Value.(json.Str); _isOk {
			test.AssertEqual(t, s.Value, "Ada")
			return
		}
		t.Error("expected Str value inside Found")
		return
	}
	t.Errorf("expected Found for a well-formed document, got %v", r)
}

// The *At/Get*Len/Each* family must validate the whole document before
// returning success (S5) — StringAt used to return a value from a valid
// path prefix with trailing garbage after the top-level value. Pairs
// with TestLookupRejectsTrailingGarbage; the *Or policy ("default on a
// malformed document") becomes reachable for tail-garbage docs too.
func TestAtFamilyRejectsTrailingGarbage(t *testing.T) {
	doc := `{"person": {"name": "Ada"}, "count": 2, "ratio": 1.5, "active": true, "tags": ["a","b"]} GARBAGE`
	_, err := json.StringAt(doc, json.KeyOf("person"), json.KeyOf("name"))
	test.AssertError(t, err)
	_, err = json.IntAt(doc, json.KeyOf("count"))
	test.AssertError(t, err)
	_, err = json.FloatAt(doc, json.KeyOf("ratio"))
	test.AssertError(t, err)
	_, err = json.BoolAt(doc, json.KeyOf("active"))
	test.AssertError(t, err)
}

// The same family still succeeds on a well-formed document (guard
// against over-validation rejecting valid input).
func TestAtFamilyAcceptsWellFormedDocument(t *testing.T) {
	doc := `{"person": {"name": "Ada"}, "count": 2, "ratio": 1.5, "active": true, "tags": ["a","b"]}`
	s, err_34 := json.StringAt(doc, json.KeyOf("person"), json.KeyOf("name"))
	if err_34 != nil {
		panic(fmt.Sprintf("%v", err_34))
	}
	test.AssertEqual(t, s, "Ada")
	n, err_35 := json.IntAt(doc, json.KeyOf("count"))
	if err_35 != nil {
		panic(fmt.Sprintf("%v", err_35))
	}
	test.AssertEqual(t, n, int64(2))
	f, err_36 := json.FloatAt(doc, json.KeyOf("ratio"))
	if err_36 != nil {
		panic(fmt.Sprintf("%v", err_36))
	}
	test.AssertEqual(t, f, 1.5)
	b, err_37 := json.BoolAt(doc, json.KeyOf("active"))
	if err_37 != nil {
		panic(fmt.Sprintf("%v", err_37))
	}
	test.AssertTrue(t, b)
}

// IntAt must reject fractional values — silently truncating 42.5 to 42
// masks data corruption. Only integer-valued JSON numbers are accepted;
// a float with a fractional part is a type mismatch.
func TestIntAtRejectsFractional(t *testing.T) {
	doc := `{"x": 42.5}`
	_, err := json.IntAt(doc, json.KeyOf("x"))
	test.AssertError(t, err)
	if !errors.Is(err, json.ErrTypeMismatch) {
		t.Errorf("expected ErrTypeMismatch for fractional IntAt, got: %v", err)
	}
}

// IntAtBytes must reject fractional values too (shared walker).
func TestIntAtBytesRejectsFractional(t *testing.T) {
	doc := []byte(`{"x": 42.5}`)
	_, err := json.IntAtBytes(doc, json.KeyOf("x"))
	test.AssertError(t, err)
	if !errors.Is(err, json.ErrTypeMismatch) {
		t.Errorf("expected ErrTypeMismatch for fractional IntAtBytes, got: %v", err)
	}
}

// IntAt must reject out-of-range integer values — a number too large
// for int64 must not silently wrap. jsontext reports the raw token, so
// ParseInt fails on overflow; the error must propagate, not collapse to
// int64 min.
func TestIntAtRejectsOutOfRange(t *testing.T) {
	doc := `{"x": 99999999999999999999999}`
	_, err := json.IntAt(doc, json.KeyOf("x"))
	test.AssertError(t, err)
}

// Out-of-range integers come back typed as ErrTypeMismatch, not the raw
// strconv parse error (S7).
func TestIntAtOutOfRangeIsTypedError(t *testing.T) {
	doc := `{"x": 99999999999999999999999}`
	_, err := json.IntAt(doc, json.KeyOf("x"))
	test.AssertError(t, err)
	if !errors.Is(err, json.ErrTypeMismatch) {
		t.Errorf("expected ErrTypeMismatch for out-of-range integer, got: %v", err)
	}
	doc2 := `{"x": 1e30}`
	_, err = json.IntAt(doc2, json.KeyOf("x"))
	test.AssertError(t, err)
	if !errors.Is(err, json.ErrTypeMismatch) {
		t.Errorf("expected ErrTypeMismatch for 1e30, got: %v", err)
	}
}

// IntAt accepts an integer-valued float at exactly 2^53 — the boundary
// is exactly representable (regression for an off-by-one guard at
// 2^53-1 that rejected 9007199254740992.0).
func TestIntAtAcceptsBoundary2Pow53(t *testing.T) {
	doc := `{"x": 9007199254740992.0}`
	n, err := json.IntAt(doc, json.KeyOf("x"))
	test.AssertNoError(t, err)
	test.AssertEqual(t, n, int64(9007199254740992))
}

// A large float-form literal must not be silently rounded to a
// neighboring int: float64 parses "9007199254740993.0" as exactly 2^53,
// so the value is re-parsed at arbitrary precision and comes back
// exactly.
func TestIntAtKeepsLiteralPrecision(t *testing.T) {
	doc := `{"x": 9007199254740993.0}`
	n, err := json.IntAt(doc, json.KeyOf("x"))
	test.AssertNoError(t, err)
	test.AssertEqual(t, n, int64(9007199254740993))
}

// IntAt still accepts a genuine integer value (regression guard so the
// fractional rejection doesn't reject valid integers).
func TestIntAtAcceptsInteger(t *testing.T) {
	doc := `{"x": 42}`
	n, err := json.IntAt(doc, json.KeyOf("x"))
	test.AssertNoError(t, err)
	test.AssertEqual(t, n, int64(42))
}

// IntAt still accepts an integer-valued float like 42.0 — JSON has one
// number kind, and 42.0 carries no fractional part, so it is a valid int.
func TestIntAtAcceptsIntegerValuedFloat(t *testing.T) {
	doc := `{"x": 42.0}`
	n, err := json.IntAt(doc, json.KeyOf("x"))
	test.AssertNoError(t, err)
	test.AssertEqual(t, n, int64(42))
}

// Duplicate object names are rejected by the v2 engine's default policy —
// the last-wins leniency of encoding/json v1 is NOT the contract here.
func TestParseRejectsDuplicateKeys(t *testing.T) {
	_, err := json.Parse[any](`{"a":1,"a":2}`)
	test.AssertError(t, err)
	_, err = json.Parse[any](`{"outer":{"x":true,"x":false}}`)
	test.AssertError(t, err)
}

// Nesting beyond the v2 engine's default depth limit is rejected rather than
// blowing the stack or silently succeeding.
func TestParseRejectsExcessiveDepth(t *testing.T) {
	doc := ""
	for range 20000 {
		doc = doc + "["
	}
	for range 20000 {
		doc = doc + "]"
	}
	_, err := json.Parse[any](doc)
	test.AssertError(t, err)
}

// Numbers beyond float64 range are rejected, not silently materialized as
// +Inf by the decoder.
func TestParseRejectsOutOfRangeNumber(t *testing.T) {
	_, err := json.Parse[any](`{"x":1e400}`)
	test.AssertError(t, err)
	_, err = json.Parse[any](`{"x":-1e400}`)
	test.AssertError(t, err)
}

// Invalid UTF-8 is rejected — the v2 engine's documented default. The doc is
// built from raw byte literals rather than "\xff" string escapes so the test
// is explicit about the exact bytes; the lexer's \xHH escape also produces
// the raw byte (Go semantics), making both forms equivalent here.
func TestParseRejectsInvalidUTF8(t *testing.T) {
	doc := []byte{0x7B, 0x22, 0x61, 0x22, 0x3A, 0x22, 0xFF, 0x22, 0x7D}
	_, err := json.ParseBytesValue(doc)
	test.AssertError(t, err)
	r := json.LookupBytes(doc, json.KeyOf("a"))
	if bad, _isOk := r.(json.Invalid); _isOk {
		test.AssertError(t, bad.Error)
		return
	}
	t.Fatal("expected Invalid for invalid UTF-8 document")
}

// The well-formed counterpart still parses: valid multi-byte UTF-8 (ÿ) in
// strings is accepted — the strictness is about invalid bytes only.
func TestParseAcceptsValidMultiByteUTF8(t *testing.T) {
	doc := []byte{0x7B, 0x22, 0x61, 0x22, 0x3A, 0x22, 0xC3, 0xBF, 0x22, 0x7D}
	_, err := json.ParseBytesValue(doc)
	test.AssertNoError(t, err)
}

// The *At family rejects documents that break mid-structure, not just
// trailing garbage (pairs with the S5 whole-document validation).
func TestAtFamilyRejectsMidDocumentMalformed(t *testing.T) {
	_, err := json.StringAt(`{"a":`, json.KeyOf("a"))
	test.AssertError(t, err)
	_, err = json.IntAt(`{"a":1`, json.KeyOf("a"))
	test.AssertError(t, err)
}

// Lookup distinguishes a present null from an absent key: null is a Found
// value, absence is the Missing data-shape arm.
func TestLookupNullVersusAbsent(t *testing.T) {
	doc := `{"a":null}`
	r := json.Lookup(doc, json.KeyOf("a"))
	if f, _isOk := r.(json.Found); _isOk {
		if _, _isOk := f.Value.(json.Null); _isOk {
			return
		}
		t.Fatal("expected Null value")
		return
	}
	t.Fatal("expected Found for present null")
	absent := json.Lookup(doc, json.KeyOf("b"))
	if _, _isOk := absent.(json.Missing); _isOk {
		return
	}
	t.Fatal("expected Missing for absent key")
}

// Empty containers are valid documents: lengths read as 0 through the
// JSONValue variant, and paths into them produce the right three-state arm.
func TestEmptyContainers(t *testing.T) {
	v, verr := json.ParseValue(`{}`)
	test.AssertNoError(t, verr)
	if o, _isOk := v.(json.Object); _isOk {
		test.AssertEqual(t, len(o.Fields), 0)
	} else {
		t.Fatal("expected Object for empty object document")
	}
	av, aerr := json.ParseValue(`[]`)
	test.AssertNoError(t, aerr)
	if a, _isOk := av.(json.Array); _isOk {
		test.AssertEqual(t, len(a.Items), 0)
	} else {
		t.Fatal("expected Array for empty array document")
	}
	r := json.Lookup(`{}`, json.KeyOf("anything"))
	if _, _isOk := r.(json.Missing); _isOk {
		return
	}
	t.Fatal("expected Missing for key into empty object")
	_, serr := json.StringAt(`[]`, json.IndexOf(0))
	test.AssertError(t, serr)
}

// Tagless decode target: no `as "..."` tags, exported Go-case fields.
type Untagged struct {
	Name string
	Port int
}

// TestParse_UntaggedCaseInsensitive pins the v1-style contract for plain
// Parse: a mismatched-case key ("name" vs the field Name) decodes into the
// field instead of silently yielding the zero value. json/v2 defaults to
// exact-case matching; plain Parse opts into MatchCaseInsensitiveNames so
// Go muscle memory carries over (issue #72). The Codec keeps its explicit
// naming policy and is not affected.
func TestParse_UntaggedCaseInsensitive(t *testing.T) {
	raw := `{"name": "snake-fails-no-more", "port": 2}`
	cfg, err := json.Parse[Untagged](raw)
	test.AssertNoError(t, err)
	test.AssertEqual(t, cfg.Name, "snake-fails-no-more")
	test.AssertEqual(t, cfg.Port, 2)
}

func TestParseBytes_UntaggedCaseInsensitive(t *testing.T) {
	raw := []byte(`{"name": "bytes", "port": 3}`)
	cfg, err := json.ParseBytes[Untagged](raw)
	test.AssertNoError(t, err)
	test.AssertEqual(t, cfg.Name, "bytes")
	test.AssertEqual(t, cfg.Port, 3)
}

func TestRead_UntaggedCaseInsensitive(t *testing.T) {
	reader := bytes.NewBufferString(`{"name": "read", "port": 4}`)
	cfg, err := json.Read[Untagged](reader)
	test.AssertNoError(t, err)
	test.AssertEqual(t, cfg.Name, "read")
	test.AssertEqual(t, cfg.Port, 4)
}

// TestParse_ExactCaseStillWorks guards the forward direction: exact-case
// keys keep decoding (the option only adds fallback, never blocks exact).
func TestParse_ExactCaseStillWorks(t *testing.T) {
	raw := `{"Name": "exact", "Port": 1}`
	cfg, err := json.Parse[Untagged](raw)
	test.AssertNoError(t, err)
	test.AssertEqual(t, cfg.Name, "exact")
	test.AssertEqual(t, cfg.Port, 1)
}

func TestParseStrict_RejectsUnknown(t *testing.T) {
	rawValid := `{"Name": "exact", "Port": 1}`
	cfg, err := json.ParseStrict[Untagged](rawValid)
	test.AssertNoError(t, err)
	test.AssertEqual(t, cfg.Name, "exact")
	rawUnknown := `{"Name": "exact", "Port": 1, "Extra": "bogus"}`
	_, uerr := json.ParseStrict[Untagged](rawUnknown)
	test.AssertError(t, uerr)
}

func TestParseBytesStrict_RejectsUnknown(t *testing.T) {
	rawUnknown := []byte(`{"Name": "exact", "Port": 1, "Bogus": 42}`)
	_, err := json.ParseBytesStrict[Untagged](rawUnknown)
	test.AssertError(t, err)
}

func TestReadStrict_RejectsUnknown(t *testing.T) {
	reader := bytes.NewBufferString(`{"Name": "exact", "Port": 1, "Spam": true}`)
	_, err := json.ReadStrict[Untagged](reader)
	test.AssertError(t, err)
}

// WebhookEvent models an open-schema payload: known fields plus an
// `,unknown` capture map for forward-compatible extras.
type WebhookEvent struct {
	ID     string         `json:"id"`
	Action string         `json:"action"`
	Extra  map[string]any `json:",unknown"`
}

func TestUnknownCapture_Parse(t *testing.T) {
	raw := "{\"id\":\"a\",\"action\":\"push\",\"foo\":\"x\",\"bar\":2,\"nested\":{\"k\":true}}"
	ev, err_38 := json.Parse[WebhookEvent](raw)
	if err_38 != nil {
		panic(fmt.Sprintf("%v", err_38))
	}
	test.AssertEqual(t, ev.ID, "a")
	test.AssertEqual(t, ev.Action, "push")
	test.AssertEqual(t, len(ev.Extra), 3)
	test.AssertEqual(t, ev.Extra["foo"], "x")
	if !(maps.Contains(ev.Extra, "nested")) {
		t.Error("nested extra missing")
	}
}

func TestUnknownCapture_CaseVariantNotLeaked(t *testing.T) {
	raw := "{\"ID\":\"b\",\"ACTION\":\"noop\",\"zzz\":9}"
	ev, err_39 := json.Parse[WebhookEvent](raw)
	if err_39 != nil {
		panic(fmt.Sprintf("%v", err_39))
	}
	test.AssertEqual(t, ev.ID, "b")
	test.AssertEqual(t, ev.Action, "noop")
	test.AssertEqual(t, len(ev.Extra), 1)
	if !(maps.Contains(ev.Extra, "zzz")) {
		t.Error("zzz should be captured")
	}
	if maps.Contains(ev.Extra, "id") || maps.Contains(ev.Extra, "ID") || maps.Contains(ev.Extra, "action") {
		t.Error("case-variant of a known field leaked into extras")
	}
}

func TestUnknownCapture_StrictCapturesInsteadOfRejecting(t *testing.T) {
	raw := "{\"id\":\"a\",\"action\":\"push\",\"foo\":\"x\"}"
	ev, err_40 := json.ParseStrict[WebhookEvent](raw)
	if err_40 != nil {
		panic(fmt.Sprintf("%v", err_40))
	}
	test.AssertEqual(t, ev.ID, "a")
	test.AssertEqual(t, len(ev.Extra), 1)
	test.AssertEqual(t, ev.Extra["foo"], "x")
}

// --- Strict × capture: the nesting contract ---
// A root `,unknown` capture field exempts only its own level. Unknown members
// of NESTED structs are still rejected by the strict entry points. Before the
// nested-validation fix, strict was dropped for the whole document when the
// root carried a capture field, so a nested unknown member was neither
// captured (the capture walk never leaves the root) nor rejected — it was
// silently discarded.
//
// The rejection is asserted by message (the jsonv2.ErrUnknownName sentinel's
// text) rather than errors.Is because json_test.kuki cannot import
// encoding/json/v2 directly: an aliased jsonv2 import poisons `json.`-qualified
// resolution against the stdlib/json petiole binding (issue 3mxmzovz7s422).
type StrictChild struct {
	Name string
}

type StrictOuter struct {
	Child StrictChild
	Extra map[string]any `json:",unknown"`
}

func TestUnknownCapture_StrictRejectsNestedUnknown(t *testing.T) {
	_, err := json.ParseStrict[StrictOuter]("{\"child\":{\"name\":\"x\",\"typo\":1}}")
	if err == nil {
		t.Error("strict must reject a nested unknown member; it returned success and silently discarded the member")
		return
	}
	if !strings.Contains(err.Error(), "unknown object member name") {
		t.Errorf("nested rejection must report jsonv2.ErrUnknownName, got: %v", err)
	}
	if !strings.Contains(err.Error(), "typo") {
		t.Errorf("error should name the unknown member, got: %v", err)
	}
}

func TestUnknownCapture_StrictStillCapturesRootUnknowns(t *testing.T) {
	ev, err_41 := json.ParseStrict[StrictOuter]("{\"child\":{\"name\":\"x\"},\"foo\":\"captured\"}")
	if err_41 != nil {
		panic(fmt.Sprintf("%v", err_41))
	}
	test.AssertEqual(t, ev.Child.Name, "x")
	test.AssertEqual(t, ev.Extra["foo"], "captured")
}

// StrictChild nested behind a pointer field: the validation walk derefs on
// the way down.
type StrictPtrOuter struct {
	Child *StrictChild
	Extra map[string]any `json:",unknown"`
}

func TestUnknownCapture_StrictRejectsNestedUnknownThroughPointer(t *testing.T) {
	_, err := json.ParseStrict[StrictPtrOuter]("{\"child\":{\"name\":\"x\",\"typo\":1}}")
	test.AssertError(t, err)
}

// Unknowns inside slice elements and map values are rejected too.
type StrictBatch struct {
	Items []StrictChild
	Extra map[string]any `json:",unknown"`
}

func TestUnknownCapture_StrictRejectsUnknownInSliceItem(t *testing.T) {
	_, err := json.ParseStrict[StrictBatch]("{\"items\":[{\"name\":\"a\"},{\"name\":\"b\",\"typo\":2}]}")
	test.AssertError(t, err)
}

type StrictRegistry struct {
	Kids  map[string]StrictChild
	Extra map[string]any `json:",unknown"`
}

func TestUnknownCapture_StrictRejectsUnknownInMapValue(t *testing.T) {
	_, err := json.ParseStrict[StrictRegistry]("{\"kids\":{\"one\":{\"name\":\"x\",\"typo\":1}}}")
	test.AssertError(t, err)
}

// Depth: the walk recurses through more than one struct level.
type StrictMid struct {
	Leaf StrictChild
}

type StrictTop struct {
	Mid   StrictMid
	Extra map[string]any `json:",unknown"`
}

func TestUnknownCapture_StrictRejectsDeepNestedUnknown(t *testing.T) {
	_, err := json.ParseStrict[StrictTop]("{\"mid\":{\"leaf\":{\"name\":\"x\",\"typo\":1}}}")
	test.AssertError(t, err)
}

// A nested struct with its own `,unknown` field is treated like any other
// nested struct under strict: capture is a root-level contract, and recursive
// capture is a tracked follow-up, not implemented.
type StrictInner struct {
	Name  string
	Extra map[string]any `json:",unknown"`
}

type StrictHolder struct {
	Inner StrictInner
	Extra map[string]any `json:",unknown"`
}

func TestUnknownCapture_StrictRejectsNestedCaptureStructUnknown(t *testing.T) {
	_, err := json.ParseStrict[StrictHolder]("{\"inner\":{\"name\":\"x\",\"typo\":1}}")
	test.AssertError(t, err)
}

// The reader entry point routes through the same validation.
func TestUnknownCapture_ReadStrictRejectsNestedUnknown(t *testing.T) {
	reader := bytes.NewBufferString("{\"child\":{\"name\":\"x\",\"typo\":1}}")
	_, err := json.ReadStrict[StrictOuter](reader)
	if err == nil {
		t.Error("strict must reject a nested unknown member; it returned success and silently discarded the member")
		return
	}
	if !strings.Contains(err.Error(), "unknown object member name") {
		t.Errorf("nested rejection must report jsonv2.ErrUnknownName, got: %v", err)
	}
}

// Non-strict stays lenient: nested unknown members are ignored (they are not
// captured — capture is root-level — but non-strict never rejects).
func TestUnknownCapture_NonStrictIgnoresNestedUnknown(t *testing.T) {
	ev, err_42 := json.Parse[StrictOuter]("{\"child\":{\"name\":\"x\",\"typo\":1},\"foo\":\"captured\"}")
	if err_42 != nil {
		panic(fmt.Sprintf("%v", err_42))
	}
	test.AssertEqual(t, ev.Child.Name, "x")
	test.AssertEqual(t, ev.Extra["foo"], "captured")
}

func TestUnknownCapture_Read(t *testing.T) {
	reader := bytes.NewBufferString("{\"id\":\"a\",\"action\":\"push\",\"foo\":\"x\"}")
	ev, err_43 := json.Read[WebhookEvent](reader)
	if err_43 != nil {
		panic(fmt.Sprintf("%v", err_43))
	}
	test.AssertEqual(t, ev.Extra["foo"], "x")
}

